for n,q,steps,ans,p in [
('2','Find the dividing point for (a) P(1,2), Q(3,4), ratio 5:7; (b) P(3,4), Q(−6,2), signed ratio 3:−2.',['Use R = (m₂P+m₁Q)/(m₁+m₂), which handles internal division and signed external weights.','For (a), choose m₁ = 5 and m₂ = 7; the denominator is 12.','Compute x = (7·1+5·3)/12 = 22/12 = 11/6.','Compute y = (7·2+5·4)/12 = 34/12 = 17/6.','For (b), use the signed weights m₁ = 3, m₂ = −2, with denominator 1.','Compute x = (−2·3+3·(−6))/1 = −24 and y = (−2·4+3·2)/1 = −2.','Check R−P = 3(Q−P): (−27,−6) = 3(−9,−2). Thus R is beyond Q, with signed PR:RQ = 3:−2.'],'(a) (11/6,17/6); (b) (−24,−2).',181),
('3','Find the centroid of A(3,−5), B(−7,4), C(10,−2).',['The centroid is the common point of the three medians.','Use G = ((x₁+x₂+x₃)/3,(y₁+y₂+y₃)/3).','Sum the horizontal coordinates: 3−7+10 = 6.','Divide by 3 to get x = 2.','Sum the vertical coordinates: −5+4−2 = −3.','Divide by 3 to get y = −1, hence G = (2,−1).','Check the midpoint of BC is (3/2,1). Moving two thirds from A toward this midpoint gives (2,−1), confirming the median ratio 2:1.'],'(2,−1).',182)]:
 EXAMPLES.append({'num':n,'title':'Section Formula' if n=='2' else 'Centroid','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':p,'jpg':'079_page_'+('1' if p==181 else '2')+'.jpg','verification':'Source question and full working visually checked'}]})
